% MATLAB and PMKS+ comparison
clc;
clear;

%% Load MATLAB results
show_plots = true;
script_folder = fileparts(mfilename('fullpath'));
source_result_file = fullfile(script_folder,'results_matlab','classroom_results.mat');
assert(isfile(source_result_file),'Run main.m first.');
MATLAB = load(source_result_file);
required = {'FirstPosition','Motion','time','Tables'};
assert(all(isfield(MATLAB,required)),'The saved MATLAB results are incomplete.');
Motion = MATLAB.Motion;
time = MATLAB.time;
assert(iscolumn(time) && numel(time)>1 && time(1)==0 && all(diff(time)>0), ...
    'MATLAB results must start at zero and use increasing time.');
output_folder = fullfile(script_folder,'results_pmks_comparison');
if ~exist(output_folder,'dir'), mkdir(output_folder); end

%% Fixed PMKS reference data
% The arrays at the end of this file are actual exported samples.
PMKS = embedded_pmks_data(time(end));
reference_joints = [1.400 .485 0; 1.670 .990 0; .255 1.035 0; ...
    .285 .055 0; .195 2.540 0; -.980 2.570 0; .050 .200 0];
if max(abs(MATLAB.FirstPosition.Joints(1:7,:)-reference_joints),[],'all')>1e-10 ...
        || max(abs(Motion.omega_AB-repmat([0 0 2*pi/2.592],numel(time),1)),[],'all')>1e-10 ...
        || any(Motion.alpha_AB~=0,'all')
    warning('PMKS:ReferenceSetupMismatch', ...
        'Embedded PMKS data require the reference A-G geometry and steady CCW input.');
    PMKS = struct;
end

%% First-position comparisons
Tables = first_position_tables(MATLAB.FirstPosition,MATLAB.Tables.Static,PMKS,output_folder);
names = fieldnames(Tables);
for j=1:numel(names)
    disp(names{j});
    disp(Tables.(names{j}));
end

%% Full-cycle comparison
PMKSComparison = compare_pmks(Motion,time,PMKS,output_folder);
disp('Full-cycle comparison:'); disp(PMKSComparison);
plot_pmks(Motion,time,PMKS,show_plots,output_folder);
save(fullfile(output_folder,'comparison_results.mat'), ...
    'Tables','PMKS','PMKSComparison','source_result_file');
fprintf('Comparison results saved to %s\n',output_folder);
fprintf('Reference data: actual PMKS exports from 2026-09-08.\n');
fprintf('NaN means no verified matching PMKS data are available.\n');

%% Local functions
function Tables=first_position_tables(first,static_table,PMKS,out)
Tables.Static=static_table;
N=height(static_table);
Tables.Static.PMKS=nan(N,1);
Tables.Static.AbsDifference=nan(N,1);
Tables.Static.Status=repmat("Not exported with matching CAD/load setup",N,1);
Tables.Static.Source=strings(N,1);
links={'AB','BC','DCE','EF','GFH'};
Tables.AngularVelocity=angular_table(links,first.omega,'omega_',"rad/s",PMKS);
Tables.AngularAcceleration=angular_table(links,first.alpha,'alpha_',"rad/s^2",PMKS);
points={'A','B','C','D','E','F','G','H'};
Tables.JointVelocity=linear_table(points,first.v,'v_',"m/s",PMKS);
Tables.JointAcceleration=linear_table(points,first.a,'a_',"m/s^2",PMKS);
Tables.COMAcceleration=linear_table({'S1','S2','S3','S4','S5'},first.a_COM,'a_',"m/s^2",PMKS);
Tables.COMAcceleration.Status(:)="No matching CAD mass-center export";
names=fieldnames(Tables);
for j=1:numel(names), writetable(Tables.(names{j}),fullfile(out,['FirstPosition_' names{j} '.csv'])); end
end

function T=angular_table(names,mat,prefix,unit,PMKS)
N=numel(names); observed=nan(N,1); status=repmat("No verified export",N,1);
q=strings(N,1); source=strings(N,1);
for j=1:N
    field=[prefix names{j}]; q(j)=string(field)+"_z";
    if isfield(PMKS,field)
        observed(j)=PMKS.(field).vector(1,3);
        status(j)="Embedded actual PMKS CSV (2026-09-08)";
        source(j)=string(PMKS.(field).source);
    end
end
T=table(q,repmat(unit,N,1),mat(:,3),observed,abs(mat(:,3)-observed),status,source, ...
    'VariableNames',{'Quantity','Unit','MATLAB','PMKS','AbsDifference','Status','Source'});
end

function T=linear_table(names,mat,prefix,unit,PMKS)
N=3*numel(names); q=strings(N,1); values=zeros(N,1); observed=nan(N,1);
status=repmat("No verified export",N,1); source=strings(N,1);
for j=1:numel(names)
    field=[prefix names{j}]; rows=3*j-2:3*j;
    q(rows)=[string(field)+"x";string(field)+"y";"|"+string(field)+"|"];
    values(rows)=[mat(j,1:2),norm(mat(j,:))]';
    if isfield(PMKS,field)
        entry=PMKS.(field);
        observed(rows)=[entry.vector(1,1:2),entry.magnitude(1)]';
        status(rows)="Embedded actual PMKS CSV (2026-09-08)";
        source(rows)=string(entry.source);
    end
end
T=table(q,repmat(unit,N,1),values,observed,abs(values-observed),status,source, ...
    'VariableNames',{'Quantity','Unit','MATLAB','PMKS','AbsDifference','Status','Source'});
end

function T=compare_pmks(Motion,time,PMKS,out)
series=strings(0,1); units=series; source=series;
max_error=[]; peak_percent=[]; sample_count=[];
names=fieldnames(PMKS);
for j=1:numel(names)
    field=names{j}; entry=PMKS.(field);
    if entry.angular, components=3; else, components=1:2; end
    for k=components
        calculated=interp1(time,Motion.(field)(:,k),entry.time,'linear');
        observed=entry.vector(:,k); difference=calculated-observed;
        peak=max(abs(calculated)); err=max(abs(difference));
        if peak>1e-12, pct=100*err/peak; else, pct=NaN; end
        series(end+1,1)=string(field)+"_"+string(char('x'+k-1)); %#ok<AGROW>
        if startsWith(field,'omega')
            u="rad/s";
        elseif startsWith(field,'alpha')
            u="rad/s^2";
        elseif startsWith(field,'v')
            u="m/s";
        else
            u="m/s^2";
        end
        units(end+1,1)=u; source(end+1,1)=string(entry.source); %#ok<AGROW>
        max_error(end+1,1)=err; peak_percent(end+1,1)=pct; sample_count(end+1,1)=numel(observed); %#ok<AGROW>
    end
end
T=table(series,units,sample_count,max_error,peak_percent,source, ...
    'VariableNames',{'Series','Unit','Samples','MaxAbsDifference','PeakScaledPercent','Source'});
writetable(T,fullfile(out,'PMKS_FullCycle_Comparison.csv'));
end

function plot_pmks(Motion,time,PMKS,show,out)
if show, visibility='on'; else, visibility='off'; end
% Embedded actual PMKS exports, with no fitted phase or amplitude adjustment.
f=figure('Name','MATLAB and PMKS comparison','NumberTitle','off','Visible',visibility,'Color','w');
layout=tiledlayout(f,2,2);
fields={'omega_BC','alpha_DCE','v_E','a_E'}; components=[3 3 1 2];
labels={'BC angular velocity (rad/s)','DCE angular acceleration (rad/s^2)', ...
    'E x velocity (m/s)','E y acceleration (m/s^2)'};
for j=1:4
    ax=nexttile(layout); hold(ax,'on'); field=fields{j}; v=Motion.(field);
    plot(ax,time,v(:,components(j)),'LineWidth',1.5,'DisplayName','MATLAB');
    if isfield(PMKS,field)
        entry=PMKS.(field);
        plot(ax,entry.time,entry.vector(:,components(j)),'--','LineWidth',1.2,'DisplayName','PMKS+ embedded export');
    else
        text(ax,.05,.9,'PMKS+ data unavailable','Units','normalized');
    end
    grid(ax,'on'); xlabel(ax,'Time (s)'); ylabel(ax,labels{j}); legend(ax,'Location','best');
end
exportgraphics(f,fullfile(out,'01_PMKS_comparison.png'),'Resolution',160);
end

